-- Code generated by factory from specs/inventory/list-stock-by-skus/spec.yaml. DO NOT EDIT.

-- name: ListStockBySkus :many
SELECT t2.sku, t2.available, t2.reserved
FROM (
    SELECT t1.sku AS sku, t1.available AS available, t1.reserved AS reserved
    FROM stock AS t1
    WHERE (t1.sku = ANY(sqlc.arg(skus)::text[]))
) AS t2
ORDER BY t2.sku COLLATE "C"
LIMIT 101;
